    score = 0

    # Evaluate age
    age_bonus = 0
    if dentist.age == 'elder':
        age_bonus = 2
    elif dentist.age == 'middle':
        age_bonus = 1

    # Evaluate attention to detail
    if dentist.attention_to_detail == 'high':
        score += 2 + age_bonus
    elif dentist.attention_to_detail == 'moderate':
        score += 1 + age_bonus

    # Evaluate technical dental skills
    if dentist.technical_dental_skills == 'excellent':
        score += 2 + age_bonus
    elif dentist.technical_dental_skills == 'satisfactory':
        score += 1 + age_bonus

    # Evaluate empathy
    if dentist.empathy == 'high':
        score += 2 - age_bonus
    elif dentist.empathy == 'moderate':
        score += 1 - age_bonus

    # Evaluate communication skills
    if dentist.communication_skills == 'excellent':
        score += 2 - age_bonus
    elif dentist.communication_skills == 'satisfactory':
        score += 1 - age_bonus

    return score
